#!/bin/bash
# build.sh step 3 (javac --release 17 against android-35 + 32 generated slot classes, then d8 --min-api 34) for the
# DEPLOYED base (ea8210a55) and the candidate. Exit status = the real javac/d8 statuses; dex hashes are reported.
set -euo pipefail
H=/home/steven/Documents/Codex/2026-10-18/wo/work/phone-dns-recovery/host-fix
SDK=/home/steven/Android/Sdk; BT=$SDK/build-tools/35.0.0; AJ=$SDK/platforms/android-35/android.jar
INSTALLED=$(sha256sum $H/../claude/host-inspect/classes.dex | cut -c1-64)
for side in base candidate; do
  S=$H/out-$side; rm -rf "$S"; mkdir -p "$S/classes" "$S/dex" "$S/gen"
  for k in $(seq 1 32); do
    printf '/* generated by build.sh: slot %s, its own process (":slot%s") */\npackage host.enclave.anchor.avf;\npublic class AnchorServiceSlot%s extends AnchorService { }\n' "$k" "$k" "$k" > "$S/gen/AnchorServiceSlot$k.java"
  done
  javac --release 17 -Xlint:-options -cp "$AJ" -d "$S/classes" $H/$side/shielded/anchor/avf/host/app/*.java "$S"/gen/*.java > "$S/javac.log" 2>&1 || { echo "$side: javac FAILED"; cat "$S/javac.log"; exit 1; }
  "$BT/d8" --min-api 34 --output "$S/dex" "$S"/classes/host/enclave/anchor/avf/*.class > "$S/d8.log" 2>&1 || { echo "$side: d8 FAILED"; cat "$S/d8.log"; exit 1; }
  d=$(sha256sum "$S/dex/classes.dex" | cut -c1-64)
  echo "$side: javac+d8 exit 0, classes.dex sha256 $d ($(stat -c %s "$S/dex/classes.dex") bytes)$([ "$d" = "$INSTALLED" ] && echo ' == INSTALLED dex')"
done
echo "installed classes.dex sha256 $INSTALLED"
